import{c as l,$ as r,Q as o,j as e,g as a,o as i,n,m as d}from"./chunks/framework.Ce_49mA8.js";const _=JSON.parse('{"title":"О философии проекта","description":"Четыре фундаментальных принципа бережливого, точного и прагматичного управленческого учета ОмниКрафт ЕРП.","frontmatter":{"title":"О философии проекта","description":"Четыре фундаментальных принципа бережливого, точного и прагматичного управленческого учета ОмниКрафт ЕРП.","order":1,"datePublished":"2026-08-20","dateModified":"2026-11-09"},"headers":[],"relativePath":"ru/docs/introduction.md","filePath":"ru/docs/introduction.md","lastUpdated":1794182400000}'),c={name:"ru/docs/introduction.md"},p={id:"о-философии-проекта",tabindex:"-1"};function u(h,t,m,v,b,f){const s=r("DocIcon");return o(),e("div",null,[a("h1",p,[i(s,{name:"philosophy"}),t[0]||(t[0]=n(" О философии проекта ",-1)),t[1]||(t[1]=a("a",{class:"header-anchor",href:"#о-философии-проекта","aria-label":'Permalink to "О философии проекта"'},"​",-1))]),t[2]||(t[2]=d('<p><strong>ОмниКрафт ЕРП</strong> создана для тех, кто созидает своими руками и головой: для мастеров-ремесленников, специалистов сферы любых услуг и владельцев собственного дела с широким бизнес-мышлением.</p><p>Классический бухгалтерский учет создавался под требования контролирующих органов: он перегружен бесконечными накладными, заумными планами счетов и сложными проводками. С другой стороны, типовые мобильные приложения для личных трат требуют нудного сканирования чеков из магазинов, но совершенно не понимают себестоимости изделий и заказ-нарядов.</p><p>В основу ОмниКрафт ЕРП заложен <strong>инженерный прагматизм</strong>: учет должен служить делу, требовать минимум времени и честно показывать реальную отдачу от каждого вложенного часа и рубля.</p><hr><h2 id="четыре-фундаментальных-принципа-омникрафт-ерп" tabindex="-1">Четыре фундаментальных принципа ОмниКрафт ЕРП <a class="header-anchor" href="#четыре-фундаментальных-принципа-омникрафт-ерп" aria-label="Permalink to &quot;Четыре фундаментальных принципа ОмниКрафт ЕРП&quot;">​</a></h2><h3 id="_1-автоматизация-вместо-бухгалтерии" tabindex="-1">1. Автоматизация вместо бухгалтерии <a class="header-anchor" href="#_1-автоматизация-вместо-бухгалтерии" aria-label="Permalink to &quot;1. Автоматизация вместо бухгалтерии&quot;">​</a></h3><p>Вам не придется сводить дебет с кредитом или собирать финансовые отчеты вручную. Аналитика рождается сама — из естественных повседневных действий в вашем направлении деятельности:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet">✓</span><div><strong>В ремесле и производстве:</strong> при закупке кожи, дерева, глины или металла партия сразу встает на склад, а расходы на доставку автоматически распределяются в себестоимость каждого дециметра или килограмма. При сборке изделия материалы списываются по скользящей средней стоимости (МАК), а готовая продукция отгружается по методу первых партий (ФИФО), мгновенно фиксируя чистую маржу.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>В сфере услуг и сервиса:</strong> будь то ремонт электроники, реставрация мебели, ногтевой сервис или частные консультации — работа строится через наглядные заказ-наряды. Программа учитывает стоимость вашего нормо-часа, автоматически списывает сопутствующие расходники (лаки, фрезы, запчасти, термопасту) прямо в заказе и принимает аванс или доплату в кассу без лишней волокиты.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Мгновенная сквозная аналитика:</strong> любое завершенное действие — приемка сырья, закрытие заказ-наряда, выпуск партии или продажа с витрины — синхронно обновляет остатки на складах, баланс кассы и отчет о прибылях.</div></li></ul><div class="info custom-block"><p class="custom-block-title">Принцип непрерывного учета</p><p>Система исключает двойную работу. Вы фиксируете только реальный физический факт работы — касса, складские остатки, себестоимость и итоговый финансовый результат пересчитываются моментально.</p></div><h3 id="_2-финансовая-эволюция-от-простого-старта-до-управления-капиталом" tabindex="-1">2. Финансовая эволюция: от простого старта до управления капиталом <a class="header-anchor" href="#_2-финансовая-эволюция-от-простого-старта-до-управления-капиталом" aria-label="Permalink to &quot;2. Финансовая эволюция: от простого старта до управления капиталом&quot;">​</a></h3><p>Большинство программ либо заставляют новичка вести строгую отчетность крупного завода, либо бросают предпринимателя, когда его деятельность перерастает одну простую таблицу. В ОмниКрафт ЕРП заложена естественная эволюция финансов по мере роста вашего дела:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet">✓</span><div><strong>Прагматичный старт без бюрократии:</strong> на начальном этапе мастера часто оплачивают расходники личной картой, а выручку направляют на текущие бытовые нужды. В программе это норма: учитываются только производственные и сервисные операции, а отрицательный остаток в отчете ДДС честно показывает сумму ваших стартовых инвестиций в проект, пока он не окупится.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Изолированные мультипространства:</strong> когда у вас появляется несколько направлений (например, мастерская изделий, сервисный кабинет и магазин сопутствующих товаров), каждое из них ведется в независимом рабочем пространстве со своей кассой, складом и клиентской базой.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Личные финансы без рабства чеков (модуль «Мой капитал»):</strong> для ведения семейного бюджета, накоплений, инвестиций и недвижимости вам не придется ежедневно записывать мелкие траты на кофе или бензин. В ПРО-режиме личные расходы рассчитываются автоматически по балансовой дельте капитала: достаточно раз в месяц сверить остатки на основных счетах, и система сама вычислит точные расходы семьи.</div></li></ul><div class="tip custom-block"><p class="custom-block-title">Плавное масштабирование</p><p>Вы начинаете с одного экрана и привычных действий. Когда дело расширяется, система открывает возможности раздельного учета нескольких проектов и консолидации всего благосостояния владельца без переучивания и потери накопленных данных.</p></div><h3 id="_3-баланс-активов-и-реальныи-финансовыи-результат" tabindex="-1">3. Баланс активов и реальный финансовый результат <a class="header-anchor" href="#_3-баланс-активов-и-реальныи-финансовыи-результат" aria-label="Permalink to &quot;3. Баланс активов и реальный финансовый результат&quot;">​</a></h3><p>Покупка японского рубанка, лазерного станка, профессионального аппарата мастера или паяльной станции уменьшает сумму на банковском счете. Но ваши средства никуда не исчезли — свободные деньги просто перешли в форму надежного рабочего оборудования, которое продолжает приносить доход.</p><p>Баланс активов и чистая стоимость всего вашего дела рассчитываются непрерывно:</p><div class="craft-callout craft-callout-info"><div class="callout-header">Формула чистых активов (Собственный капитал)</div><p><strong>Собственный капитал</strong> = Остаточная стоимость станков и оборудования + Сырье и расходники на складе (по МАК) + Готовые изделия (по себестоимости) + Свободные средства на счетах и в кассах + Личные резервы и инвестиции (в модуле капитала) − Обязательства и долги.</p></div><h4 id="триединство-финансовых-отчетов" tabindex="-1">Триединство финансовых отчетов <a class="header-anchor" href="#триединство-финансовых-отчетов" aria-label="Permalink to &quot;Триединство финансовых отчетов&quot;">​</a></h4><p>Три классических показателя дополняют друг друга и защищают мастера и предпринимателя от опасных иллюзий и кассовых разрывов:</p><div class="comparison-matrix-wrapper"><table class="craft-comparison-table"><thead><tr><th style="width:24%;">Отчет</th><th style="width:28%;">Главный вопрос</th><th style="width:48%;">Практический смысл для мастера и дела</th></tr></thead><tbody><tr><td><strong>ДДС</strong><br><small style="color:var(--vp-c-text-3);">Движение денег</small></td><td><em>Есть ли средства прямо сейчас?</em></td><td>Отражает физический поток наличных и безналичных оплат. Защищает от кассового разрыва: помогает вовремя оплатить аренду помещения, расходники или счета поставщиков.</td></tr><tr><td><strong>Прибыль (ОПиУ)</strong><br><small style="color:var(--vp-c-text-3);">Финансовый результат</small></td><td><em>Выгодно ли то, что вы делаете?</em></td><td>Сопоставляет фактические доходы с полными расходами (с учетом износа оборудования, списанных материалов и накладных затрат). Показывает истинную прибыльность изделий, заказ-нарядов и услуг.</td></tr><tr><td><strong>Баланс</strong><br><small style="color:var(--vp-c-text-3);">Чистые активы</small></td><td><em>Сколько стоит все ваше дело?</em></td><td>Объединяет все имущество (оборудование, инструмент, сырье, готовые товары, кассу и инвестиции) за вычетом долгов. Показывает, растет ли ценность вашего дела и личного капитала из года в год.</td></tr></tbody></table></div><div class="tip custom-block"><p class="custom-block-title">Автоматические снимки состояния</p><p>Система регулярно сохраняет контрольные слепки ключевых показателей. Это позволяет наглядно видеть динамику развития: сезонные колебания выручки внутри месяцев и стратегический рост совокупного капитала за годы работы.</p></div><h3 id="_4-приватность-независимость-и-ии-прямого-доступа" tabindex="-1">4. Приватность, независимость и ИИ прямого доступа <a class="header-anchor" href="#_4-приватность-независимость-и-ии-прямого-доступа" aria-label="Permalink to &quot;4. Приватность, независимость и ИИ прямого доступа&quot;">​</a></h3><p>ОмниКрафт ЕРП построена на принципах уважения к суверенитету ваших данных. Программа работает автономно на вашем компьютере и не зависит от доступности облачных серверов или риска внезапных блокировок.</p><ul class="craft-feature-list"><li><span class="craft-list-bullet">✓</span><div><strong>Полная автономность и конфиденциальность:</strong> базы данных хранятся локально на вашем ПК. Сметы, рецепты изделий, списки клиентов и балансы счетов никогда не передаются на сторонние серверы разработчиков.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Прямой личный ключ к ИИ без посредников:</strong> запросы к нейросетям отправляются с вашего устройства напрямую к выбранному провайдеру (`OpenAI`, `Google Gemini`, `DeepSeek`, `OpenRouter`) либо обрабатываются полностью офлайн через локальный сервис `Ollama`.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Прикладные помощники на рабочих экранах:</strong> компактные кнопки ускоряют рутину прямо в рабочих формах — экспресс-проверка сметы изделия, расчет расхода материалов, формулирование рекомендаций в заказ-наряде и подготовка складских описаний.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Интеграция по открытому протоколу контекста моделей (`Model Context Protocol`, `MCP`):</strong> открытый протокол позволяет внешним ИИ-ассистентам и автономным агентам напрямую подключаться к данным программы через современные инженерные среды разработки (`Cursor`, `Claude Desktop`, `Antigravity`).</div></li></ul>',24))])}const k=l(c,[["render",u]]);export{_ as __pageData,k as default};
